def first_occurrence(haystack, needle):
    n = len(haystack)
    m = len(needle)
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if haystack[i + j] != needle[j]:
                match = False
                break
        if match:
            return i
    return -1
